<?php
require_once __DIR__.'/layout.php';$admin=require_role(['admin']);$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='create'){$username=trim($_POST['username']??'');$name=trim($_POST['full_name']??'');$role=$_POST['role']??'teacher';$pass=$_POST['password']??'';if($username&&$name&&strlen($pass)>=8){try{$st=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,?)');$st->execute([$username,password_hash($pass,PASSWORD_DEFAULT),$name,$role]);flash('success','Usuario creado.');}catch(Throwable $e){flash('error','No se pudo crear; el usuario puede estar repetido.');}}else flash('error','Complete los campos. La contraseña debe tener al menos 8 caracteres.');header('Location: users.php');exit;}if($action==='toggle'){$id=(int)$_POST['id'];if($id!==$admin['id'])$pdo->prepare('UPDATE users SET active=1-active WHERE id=?')->execute([$id]);flash('success','Estado actualizado.');header('Location: users.php');exit;}}
$users=$pdo->query('SELECT * FROM users ORDER BY active DESC,full_name')->fetchAll();app_header('Usuarios'); ?>
<div class="panel"><h2>Crear usuario</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="form-grid"><label class="c3">Usuario<input name="username" required></label><label class="c4">Nombre completo<input name="full_name" required></label><label class="c3">Rol<select name="role"><option value="teacher">Docente</option><option value="coordinator">Coordinador</option><option value="director">Director</option><option value="admin">Administrador</option></select></label><label class="c2">Contraseña<input type="password" name="password" minlength="8" required></label></div><div class="actions"><button class="button">Crear usuario</button></div></form></div>
<div class="panel"><h2>Usuarios del sistema</h2><div class="table-wrap"><table class="sys-table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($users as $x):?><tr><td><?=h($x['full_name'])?></td><td><?=h($x['username'])?></td><td><?=h(role_label($x['role']))?></td><td><?=$x['active']?'<span class="badge">Activo</span>':'Inactivo'?></td><td><?php if($x['id']!=$admin['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="button gray"><?=$x['active']?'Desactivar':'Activar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php app_footer(); ?>
